"""Exact visual orb crop from the user-approved JARVIS interface reference.

Stored as WebP/base64 so the release remains self-contained and PyInstaller can
ship the exact approved hero visual without relying on an external asset URL.
"""
from __future__ import annotations

import base64
import io
from PIL import Image

_ORB_WEBP_B64 = """"""


def load_orb_image() -> Image.Image:
    return Image.open(io.BytesIO(base64.b64decode(_ORB_WEBP_B64))).convert("RGBA")


__all__ = ["load_orb_image"]
